--
-- Схема тестовой БД: дамп public-схемы прода (dev.dsconsult.ru) + состояние
-- миграций + данные справочников. Снят 2026-08-14.
--
-- ЗАЧЕМ ФАЙЛ ВООБЩЕ ЕСТЬ: legacy-таблицы (transaction, consultant, commission,
-- contract и ещё ~300) НЕ создаются миграциями — схема пришла дампом из
-- Directual, а миграции только патчат её. Поэтому RefreshDatabase не может
-- собрать тестовую БД из миграций, и до появления этого файла тесты с БД не
-- запускались нигде: ни локально, ни в CI.
--
-- Laravel грузит его сам (PostgresSchemaState) при migrate/migrate:fresh,
-- когда таблица migrations пуста, и дальше догоняет миграции, которых нет в
-- зафиксированном ниже состоянии.
--
-- ЧТО ВНУТРИ ДАННЫХ: только словари — statuses, уровни квалификаций, валюты и
-- их курсы, ставка НДС, системные настройки, группы прав, свойства КВ,
-- страны/города. Персональных данных и бизнес-строк (контракты, транзакции,
-- комиссии, партнёры) здесь НЕТ: каждый тест создаёт их сам под свой сценарий.
--
-- КАК ОБНОВИТЬ (после изменения прод-схемы):
--   pg_dump -U newds -d newds --schema-only --no-owner --no-privileges \
--           --no-comments -n public                          > raw.sql
--   pg_dump -U newds -d newds --data-only --no-owner -t public.migrations >> raw.sql
--   pg_dump -U newds -d newds --data-only --no-owner \
--           -t public.statuses -t public.status_levels ...    >> raw.sql
-- затем убрать meta-команды \restrict/\unrestrict, заменить CREATE SCHEMA
-- public на IF NOT EXISTS и дописать ресинк сиквенсов (блок в конце файла).
--

