--
-- Name: product; Type: VIEW; Schema: public; Owner: -
--

CREATE VIEW public.product AS
 SELECT id,
    name,
    type AS "typeName",
    active,
    visible_to_resident AS "visibleToResident",
    visible_to_calculator AS "visibleToCalculator",
    form_link AS "formLink",
    open_product_url AS "openProductUrl",
    education_url AS "educationUrl",
    instruction_url AS "instructionUrl",
    image_url AS "imageUrl",
    hero_image,
    description,
    priority,
    has_property,
    has_term,
    has_year_kv,
    no_commission AS "noComission",
        CASE
            WHEN active THEN 'published'::text
            ELSE 'draft'::text
        END AS publish_status,
    created_at AS published_at,
    NULL::integer AS published_by,
    NULL::text AS "tagList",
    NULL::integer AS "productTags",
    NULL::integer AS "motivationGroup",
    NULL::integer AS ambassador,
    NULL::integer AS access,
    NULL::integer AS "productType"
   FROM public.products_catalog;


