COMMIT;


--
-- Пересинхронизация сиквенсов под вставленные id: иначе первый же INSERT в
-- тесте ловит duplicate key — та же грабля, что на проде после восстановления
-- из дампа.
--
-- ⚠ Идём по КОЛОНКАМ через pg_get_serial_sequence, а не по pg_depend с
-- deptype='a': у GENERATED AS IDENTITY (например commission.id) зависимость
-- помечена 'i', и обход по 'a' такие колонки пропускает — ровно те, куда
-- тесты вставляют больше всего строк.
--
DO $$
DECLARE r record; seq text;
BEGIN
    FOR r IN
        SELECT c.table_name AS tbl, c.column_name AS col
          FROM information_schema.columns c
          JOIN information_schema.tables t
            ON t.table_schema = c.table_schema AND t.table_name = c.table_name
         WHERE c.table_schema = 'public'
           AND t.table_type = 'BASE TABLE'
           AND (c.is_identity = 'YES' OR c.column_default LIKE 'nextval%')
    LOOP
        seq := pg_get_serial_sequence(format('public.%I', r.tbl), r.col);
        IF seq IS NOT NULL THEN
            EXECUTE format(
                'SELECT setval(%L, COALESCE((SELECT MAX(%I) FROM public.%I), 0) + 1, false)',
                seq, r.col, r.tbl
            );
        END IF;
    END LOOP;
END $$;
